-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=0.0, y=-0.5}
p001 = Vector3:new{x=0.5, y=0.0}
p002 = Vector3:new{x=0.0, y=0.0}
p003 = Vector3:new{x=0.0, y=0.5}
p004 = Vector3:new{x=2.0, y=2.0}
p005 = Vector3:new{x=0.35355339059327373, y=0.35355339059327373}
p006 = Vector3:new{x=2.0, y=-2.0}
p007 = Vector3:new{x=0.35355339059327373, y=-0.35355339059327373}
p008 = Vector3:new{x=-0.5, y=0.0}
p009 = Vector3:new{x=-2.0, y=2.0}
p010 = Vector3:new{x=-0.35355339059327373, y=0.35355339059327373}
p011 = Vector3:new{x=-2.0, y=-2.0}
p012 = Vector3:new{x=-0.35355339059327373, y=-0.35355339059327373}

-- paths
path_c8 = Arc:new{p0=p000, p1=p001, centre=p002}
path_c5 = Arc:new{p0=p001, p1=p003, centre=p002}
path_c11 = Line:new{p0=p004, p1=p005}
path_c2 = Line:new{p0=p006, p1=p004}
path_c10 = Line:new{p0=p006, p1=p007}
path_c6 = Arc:new{p0=p003, p1=p008, centre=p002}
path_c12 = Line:new{p0=p009, p1=p010}
path_c3 = Line:new{p0=p004, p1=p009}
path_c7 = Arc:new{p0=p008, p1=p000, centre=p002}
path_c1 = Line:new{p0=p011, p1=p006}
path_c9 = Line:new{p0=p011, p1=p012}
path_c4 = Line:new{p0=p009, p1=p011}

-- blocks
blocks = {}
-- block blk1
surf_blk1 = CoonsPatch:new{north=Polyline:new{segments={SubRangedPath:new{underlying_path=path_c8, t0=0.5, t1=1.0}, SubRangedPath:new{underlying_path=path_c5, t0=0.0, t1=0.5}}}, east=path_c11, south=path_c2, west=path_c10}
grid_blk1 = StructuredGrid:new{psurface=surf_blk1, niv=13, njv=13, label="blk1"}
blocks[#blocks+1] = {grid=grid_blk1, tag="blk1", fsTag="initial", bcTags={}}

-- block blk2
surf_blk2 = CoonsPatch:new{north=path_c11, east=Polyline:new{segments={SubRangedPath:new{underlying_path=path_c6, t0=0.5, t1=0.0}, SubRangedPath:new{underlying_path=path_c5, t0=1.0, t1=0.5}}}, south=path_c12, west=ReversedPath:new{underlying_path=path_c3}}
grid_blk2 = StructuredGrid:new{psurface=surf_blk2, niv=13, njv=13, label="blk2"}
blocks[#blocks+1] = {grid=grid_blk2, tag="blk2", fsTag="initial", bcTags={}}

-- block blk3
surf_blk3 = CoonsPatch:new{north=Polyline:new{segments={SubRangedPath:new{underlying_path=path_c7, t0=0.5, t1=1.0}, SubRangedPath:new{underlying_path=path_c8, t0=0.0, t1=0.5}}}, east=path_c10, south=path_c1, west=path_c9}
grid_blk3 = StructuredGrid:new{psurface=surf_blk3, niv=13, njv=13, label="blk3"}
blocks[#blocks+1] = {grid=grid_blk3, tag="blk3", fsTag="initial", bcTags={}}

-- block blk4
surf_blk4 = CoonsPatch:new{north=path_c12, east=Polyline:new{segments={SubRangedPath:new{underlying_path=path_c7, t0=0.5, t1=0.0}, SubRangedPath:new{underlying_path=path_c6, t0=1.0, t1=0.5}}}, south=path_c9, west=ReversedPath:new{underlying_path=path_c4}}
grid_blk4 = StructuredGrid:new{psurface=surf_blk4, niv=13, njv=13, label="blk4"}
blocks[#blocks+1] = {grid=grid_blk4, tag="blk4", fsTag="initial", bcTags={}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "east", ids[2], "north")
   connectGrids(ids[1], "west", ids[3], "east")
   connectGrids(ids[2], "south", ids[4], "north")
   connectGrids(ids[3], "west", ids[4], "south")
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
